CREATE OR REPLACE PROCEDURE sp(
    para_Injured integer,
    para_Country text,
    para_Height real,
    para_Name text
)
LANGUAGE plpgsql
AS $$
DECLARE
    rec_id integer;
    rec_val text;
    processed_count integer := 0;
    max_injured_seen integer := NULL;
    cur CURSOR FOR
        SELECT Injured, Country
        FROM offender
        WHERE Injured > para_Injured
        ORDER BY Injured DESC, Country ASC, Perpetrator_ID ASC
        LIMIT 10;
BEGIN
    UPDATE offender SET Country = 'initial';
    DELETE FROM people WHERE Name IS NULL;
    OPEN cur;
    LOOP
        FETCH cur INTO rec_id, rec_val;
        EXIT WHEN NOT FOUND;
        processed_count := processed_count + 1;
        IF max_injured_seen IS NULL OR rec_id > max_injured_seen THEN
            max_injured_seen := rec_id;
        END IF;
        IF rec_id > 1000 THEN
            DELETE FROM offender WHERE Injured = rec_id;
            DELETE FROM people WHERE Height = rec_id;
        ELSIF rec_id > 100 THEN
            UPDATE offender SET Country = rec_val || '_updated' WHERE Injured = rec_id;
            UPDATE people SET Name = 'UPDATED_LOG' WHERE Height = rec_id;
        ELSE
            UPDATE offender SET Country = rec_val || '_checked' WHERE Injured = rec_id;
            DELETE FROM people WHERE Height = rec_id;
        END IF;
    END LOOP;
    CLOSE cur;

    UPDATE offender SET Country = 'finished';
    UPDATE people SET Name = 'finished_log';
    DELETE FROM offender WHERE Country IS NULL;
    DELETE FROM people WHERE Name IS NULL;
    UPDATE offender SET Country = 'final_pass';
    UPDATE people SET Name = 'log';
    DELETE FROM offender WHERE Country LIKE '%error%';
    DELETE FROM people WHERE Name LIKE '%error%';
    UPDATE offender SET Country = para_Country;
    UPDATE people SET Name = para_Name;
    DELETE FROM offender WHERE Injured = para_Injured;
    DELETE FROM people WHERE Height = para_Height;
    IF processed_count > 0 THEN
        DELETE FROM people WHERE Height > para_Height;
    END IF;
    IF max_injured_seen IS NOT NULL AND max_injured_seen > para_Injured THEN
        UPDATE offender SET Country = para_Country || '_max' WHERE Injured = max_injured_seen;
    END IF;
END;
$$;

